INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (7, '商务英语词汇', 'BEC_2', '精选商务英语初级、中级、高级考试及实际应用词汇。通过科学频率算法筛选高频核心词汇，专业团队把关，帮助用户节约时间、高效学习。精选例句和词组短语，帮助用户准确把握用词含义，快速掌握真实场景的运用。结合背单词科学记忆方法，有利于用户迅速掌握商务词汇，有效扩大词汇量，提高考试成绩。适用于备战考试，有意丰富自身商务英语词汇的用户。', 2753, 0);
