INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (20, '四级真题核心词（正序版）', 'CET4_1', '有道超强词频统计，考神团队精心制作。整合历届大学英语四级真题中出现的所有单词，将3739个四级词汇通过科学的频率算法，考神团队专业把控，筛选至考试必背的1162个核心词汇。搭配背单词近十年真题例句，感受最真实的考试情境，在语境中加深理解。面包君带你用最短的时间考最高的分数！适用于考生备战考试、用户高效学习。', 1162, 0);
INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (21, '四级英语词汇（正序版）', 'CET4_2', '据教育部最新颁发大学英语课程教学要求制作，四级备考用户基础经典必背词书。整合收录中学基础词汇、四级大纲要求词汇、真题高频词汇、超纲词汇。有道词典提供正版权威词库，名师校编给你最需要的单词释义和例句，配合背单词科学记忆方法，简单有效搞定四级，此书在手，天下我有！适合所有四级备考用户或想夯实英语基础能力的用户。', 3739, 0);
