INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (25, '六级真题核心词（正序版）', 'CET6_1', '有道超强词频统计，考神团队精心制作。整合六级大纲词汇、历届六级真题词汇，排除简单词汇，将2078个历届六级考试中出现的单词，通过科学的频率算法，专业团队的把关，筛选至1228个必背核心词汇，帮助用户在短期内实现六级词汇量的突破。结合面包记忆法与真题例句提供的真实考试场景，面包君带你用最短的时间搞定六级！适用于考生备战考试，用户高效学习。', 1228, 0);
