INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (29, '初中英语词汇（正序版）', 'CHUZHONG_2', '依据教育部最新颁布的英语课程标准，初中英语考试常考点和必考点，整合收录初中英语核心词汇及基础词汇。有道词典提供权威正版词库，名师校编给你最需要的单词释意，搭配例句给你完整的语境理解单词含义，加深学习印象。词组短语教你如何实际运用，必考搭配一网打尽。适合备战中考以及初中阶段学习英语的所有用户。', 1420, 0);
