INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (35, 'GMAT词汇（正序版）', 'GMAT_2', '全面整合收录GMAT官方指南、真题实战中的考试词汇。有道词典提供正版权威词库，从考点出发，以真题为基础，剔除简单词汇，国外权威辞典给出释意和例句，加深用户对单词本身含义的理解和记忆，帮助用户高效学习。每个单词均列出短语和多项近义词，有效扩展词汇量并提高记忆效率，帮助用户从容应对词汇难度和用法都更具挑战性的GMAT考试。适合准备GMAT考试，想要提高英语能力的用户。', 3254, 0);
