INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (43, '考研必考词汇（正序版）', 'KAOYAN_1', '有道超强词频统计，考神团队精心制作。严格按照考研英语最新大纲要求，运用科学的统计算法，考神团队深入研究历年真题及考研英语命题规律，对考研英语词汇进行深入地分析和研究，统计真实考试场景下的必背词汇，名师把关剔除简单词汇，将4533个考研词汇通过严格科学的方法筛选至1341个核心词，帮助考生省时省力完成备考，快速高效！', 1341, 0);
INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (44, '考研英语词汇', 'KAOYAN_2', '严格根据最新考研英语词汇大纲要求制作，考研备考用户基础经典必背词书。在必考词汇的基础之上，全面兼顾了真实考试场景下所涉及的所有基础词汇、高频词汇。有道词典提供正版权威词库，名师校编给你最需要的单词释义和例句。配合背单词科学记忆方法，面包君陪你一起走完考研之路。背完这本，心里踏实。适合所有考研备考用户。', 4533, 0);
