INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (46, '考研必考词汇', 'KAOYANLUAN_1', '有道超强词频统计，考神团队诚意出品。严格按照考研英语最新大纲要求，运用科学的统计算法，考神团队深入研究历年真题及考研英语命题规律，对考研英语词汇进行深入地分析和研究，统计真实考试场景下的必背词汇，名师把关剔除简单词汇，将4533个考研词汇通过严格科学的方法筛选至1341个核心词，帮助考生省时省力完成备考！适合考研用户。', 1341, 0);
INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (47, '专四真题高频词（正序版）', 'LEVEL4_1', '有道超强词频统计，考神团队精心制作。整合历年专四真题考试中的所有词汇，通过深入研究改革前后历年真题命题规律，对专四真题词汇进行深入分析和研究，统计真实考试场景下必背595个高频词汇。乱序编排，灵活背词。搭配英文释意，帮助考生准确理解词义，满足专四更高需求。用最短的时间考最高的分数，背单词带你搞定专四，快、准、狠！适用于高效学习、基础备考。', 595, 0);
