INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (78, 'SAT词汇', 'SAT_2', '全面收录SAT考试词汇4423个，有道词典提供正版权威词库，参考College Board官方推荐权威辞典给出的单词释意及例句，帮助考生在语境中加深对单词的理解，更有针对性地备考。每个单词均列出短语和多项近义词，帮助考生掌握词汇实际运用方法，应对一词多义、一次多用的情况。适合准备SAT考试的用户以及英语学习爱好者。', 4423, 0);
