INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (80, 'TOEFL词汇', 'TOEFL_2', '整合收录托福考试指南、TPO真题词汇共9213个单词。有道词典提供正版权威词库，国外权威辞典例句和英文释意，帮助用户把握词汇命脉，在学习过程中更好地理解词汇原汁原味的含义。每个单词均列出短语和多项近义词，有效扩展词汇量并提高记忆效率，帮助用户从容应对词汇难度和用法都更具挑战性的托福考试。适合准备托福考试，想要提高英语能力的用户。', 9213, 0);
INSERT INTO `biz_vocabulary_books`(`id`, `name`, `code`, `description`, `total_words`, `sort_order`) VALUES (81, '新东方TOEFL词汇', 'TOEFL_3', 'TOEFL 3词汇书，包含丰富的单词释义、例句、短语、同义词、反义词等学习资源。', 4264, 0);
